Definition mk_1RB0LC_1RC1LD_0LD0RC_1LA1LB (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB0LC_1RC1LD_0LD0RC_1LA1LB.

(** 1RB0LC_1RC1LD_0LD0RC_1LA1LB *)
Definition tm_1RB0LC_1RC1LD_0LD0RC_1LA1LB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DR StC
  | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S0 DL StD
  | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S1 DL StA
  | StD, S1 => mk S1 DL StB
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB0LC_1RC1LD_0LD0RC_1LA1LB : list Instr := [(StA, S1)].
Local Notation tm := (tm_wrap_trs tm_1RB0LC_1RC1LD_0LD0RC_1LA1LB pins_1RB0LC_1RC1LD_0LD0RC_1LA1LB).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB0LC_1RC1LD_0LD0RC_1LA1LB : Fam := mkFam 2 [[S0;S0;S0];[S0;S0;S1]] [] [[]] Binary 1 [mkFill 1 [] 0 [1] 0] StC S0 true [S0;S1;S1;S1;S1].
Local Notation FAM := fam_1RB0LC_1RC1LD_0LD0RC_1LA1LB.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0LC_1RC1LD_0LD0RC_1LA1LB : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [S0;S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1;S1;S1] [] 0 0 [])) 0 5, [RB (SWin 5)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StC (mkS [S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)])].
Local Notation lad := lad_1RB0LC_1RC1LD_0LD0RC_1LA1LB.

Definition rules_1RB0LC_1RC1LD_0LD0RC_1LA1LB : list LRule := map fst lad.
Local Notation rules := rules_1RB0LC_1RC1LD_0LD0RC_1LA1LB.

Lemma ladder_ok_1RB0LC_1RC1LD_0LD0RC_1LA1LB : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0LC_1RC1LD_0LD0RC_1LA1LB : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0LC_1RC1LD_0LD0RC_1LA1LB. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
