Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0LD_1LC0LC_1RD1LB_1LA0RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LD_1LC0LC_1RD1LB_1LA0RD
  | _, _ => iarm0_0_1RB0LD_1LC0LC_1RD1LB_1LA0RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

