  match r, t with
  | 1, (StA, S0) => []
  | 1, (StB, S0) => [SWin 3]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWin 4;SCycL 2 0;SWinL 2]
  | 1, (StC, S1) => [SWin 2]
  | 1, (StD, S0) => [SWin 4;SCycL 2 0;SWinL 4;SCycR 2;SWin 3]
  | 1, (StD, S1) => [SWin 4;SCycL 2 0;SWinL 3]
  | _, _ => []
  end.

