  lr_rhs (farm_1RB1LD_1LC1LA_1RD1LB_0LC0RD r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_1RB1LD_1LC1LA_1RD1LB_0LC0RD r ph)
