Definition tm_1RB1LD_1RC0RB_1LA0RB_0LD1LB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S1 DR StC
  | StB, S1 => mk S0 DR StB
  | StC, S0 => mk S1 DL StA
  | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S0 DL StD
  | StD, S1 => mk S1 DL StB
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB1LD_1RC0RB_1LA0RB_0LD1LB : list Instr := [(StA, S0)].
Local Notation tm := (tm_wrap_trs tm_1RB1LD_1RC0RB_1LA0RB_0LD1LB pins_1RB1LD_1RC0RB_1LA0RB_0LD1LB).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1LD_1RC0RB_1LA0RB_0LD1LB : Fam := mkFam 2 [[S0;S0];[S1;S1]] [] [[]] Binary 1 [mkFill 1 [] 0 [1] 0] StC S0 false [S1;S0;S0;S1;S0;S0;S1;S0;S1].
Local Notation FAM := fam_1RB1LD_1RC0RB_1LA0RB_0LD1LB.

(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1LD_1RC0RB_1LA0RB_0LD1LB : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StB (mkS [S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StD (mkS [S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StB (mkS [S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)])].
Local Notation lad := lad_1RB1LD_1RC0RB_1LA0RB_0LD1LB.

Definition rules_1RB1LD_1RC0RB_1LA0RB_0LD1LB : list LRule := map fst lad.
Local Notation rules := rules_1RB1LD_1RC0RB_1LA0RB_0LD1LB.

Lemma ladder_ok_1RB1LD_1RC0RB_1LA0RB_0LD1LB : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1LD_1RC0RB_1LA0RB_0LD1LB : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1LD_1RC0RB_1LA0RB_0LD1LB. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(* C[0] L<100^2 1^1 0^1 1^1> R<>  ==>  C[0] L<1^1 0^2 1^1 0^2 1^1 0^1 1^1> R<1^2>   [40 steps] *)
Definition arm15_1RB1LD_1RC0RB_1LA0RB_0LD1LB : LRule :=
  mkLRule (mkC StC (mkS [S1;S0;S0;S1;S0;S0;S1;S0;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StC (mkS [S1;S0;S0;S1;S0;S0;S1;S0;S1] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 [])) 0 40.
Definition ch_arm15_1RB1LD_1RC0RB_1LA0RB_0LD1LB : list rstep := [RB (SWin 18);RB (SWinR 22)].
Lemma ok_arm15_1RB1LD_1RC0RB_1LA0RB_0LD1LB :
  check_arm tm true true rules arm15_1RB1LD_1RC0RB_1LA0RB_0LD1LB ch_arm15_1RB1LD_1RC0RB_1LA0RB_0LD1LB = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm15_1RB1LD_1RC0RB_1LA0RB_0LD1LB : RuleSound tm true true arm15_1RB1LD_1RC0RB_1LA0RB_0LD1LB.
Proof. eapply arm_sound; [exact rules_sound_1RB1LD_1RC0RB_1LA0RB_0LD1LB | exact ok_arm15_1RB1LD_1RC0RB_1LA0RB_0LD1LB]. Qed.

(* C[0] L<100^2 1^1 0^1 1^1> R<1^2+y0>  ==>  C[0] L<1^1 0^2 1^1 0^2 1^1 0^1 1^1> R<0^2+y0 1^2>   [44+2*y0 steps] *)
Definition arm5_1RB1LD_1RC0RB_1LA0RB_0LD1LB : LRule :=
  mkLRule (mkC StC (mkS [S1;S0;S0;S1;S0;S0;S1;S0;S1] [] 0 0 []) S0 (mkS [S1;S1] [S1] 1 0 []))
          (mkC StC (mkS [S1;S0;S0;S1;S0;S0;S1;S0;S1] [] 0 0 []) S0 (mkS [S0;S0] [S0] 1 0 [S1;S1])) 2 44.
Definition ch_arm5_1RB1LD_1RC0RB_1LA0RB_0LD1LB : list rstep := [RB (SWin 20);RB (SCycR 1);RB (SWinR 4);RB (SCycL 1 0);RB (SWin 20)].
Lemma ok_arm5_1RB1LD_1RC0RB_1LA0RB_0LD1LB :
  check_arm tm true true rules arm5_1RB1LD_1RC0RB_1LA0RB_0LD1LB ch_arm5_1RB1LD_1RC0RB_1LA0RB_0LD1LB = true.
Proof. vm_compute. reflexivity. Qed.
