(* C[0] L<100^2 1^1 0^1 1^1> R<0^2+y0 1^2+y1>  ==>  C[0] L<1^1 0^2 1^1 0^2 1^1 0^1 1^1> R<1^2 0^y0 1^2+y1>   [40 steps] *)
Definition arm4_1RB1LD_1RC0RB_1LA0RB_0LD1LB : LRule :=
  mkLRule (mkC StC (mkS [S1;S0;S0;S1;S0;S0;S1;S0;S1] [] 0 0 []) S0 (mkS [S0;S0] [] 0 0 []))
          (mkC StC (mkS [S1;S0;S0;S1;S0;S0;S1;S0;S1] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 [])) 0 40.
Definition ch_arm4_1RB1LD_1RC0RB_1LA0RB_0LD1LB : list rstep := [RB (SWin 40)].
Lemma ok_arm4_1RB1LD_1RC0RB_1LA0RB_0LD1LB :
