(* C[0] L<100^2 1^1 0^1 1^1> R<1^2+y0 0^2+y1 1^2+y2 #^1>  ==>  C[0] L<1^1 0^2 1^1 0^2 1^1 0^1 1^1> R<0^2+y0 1^2 0^y1 1^2+y2 #^1>   [44+2*y0 steps] *)
Definition arm2_1RB1LD_1RC0RB_1LA0RB_0LD1LB : LRule :=
