          (mkC StC (mkS [S1;S0;S0;S1;S0;S0;S1;S0;S1] [] 0 0 []) S0 (mkS [S0;S0] [S0] 1 0 [S1;S1])) 2 44.
Definition ch_arm2_1RB1LD_1RC0RB_1LA0RB_0LD1LB : list rstep := [RB (SWin 20);RB (SCycR 1);RB (SWin 4);RB (SCycL 1 0);RB (SWin 20)].
Lemma ok_arm2_1RB1LD_1RC0RB_1LA0RB_0LD1LB :
  check_arm tm true false rules arm2_1RB1LD_1RC0RB_1LA0RB_0LD1LB ch_arm2_1RB1LD_1RC0RB_1LA0RB_0LD1LB = true.
