(** The boot, on the ORIGINAL machine and up to [lift]: the member at index
    32, past the last fire of every pinned instruction. *)
Lemma bootq_1RB1LD_1RC0RB_1LA0RB_0LD1LB :
  stepn tm_1RB1LD_1RC0RB_1LA0RB_0LD1LB 32 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm_1RB1LD_1RC0RB_1LA0RB_0LD1LB 32 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm_1RB1LD_1RC0RB_1LA0RB_0LD1LB 32 c0) as [c|] eqn:E; [|discriminate].
