Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1LD_1RC1RB_1LA1LA_0RB0LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LD_1RC1RB_1LA1LA_0RB0LD
  | 0, 1 => iarm0_1_1RB1LD_1RC1RB_1LA1LA_0RB0LD
  | _, _ => iarm0_0_1RB1LD_1RC1RB_1LA1LA_0RB0LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1LD_1RC1RB_1LA1LA_0RB0LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [S1;S1] 1 0 [S0;S1;S1]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [S0;S0] 1 0 [S1;S1;S1])) 4 8.
