Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LD_1RC1RB_1LA1LA_0RB0LD | exact ok_iarm0_0_1RB1LD_1RC1RB_1LA1LA_0RB0LD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LD_1RC1RB_1LA1LA_0RB0LD | exact ok_iarm0_1_1RB1LD_1RC1RB_1LA1LA_0RB0LD]. }
    exfalso; lia.
