(** The machine-level theorem, on the QUASIHALTING side: the board above
    runs on the machine wrapped at the pins from the boot member on, and
    [LadderCheckQHTr.boardph_qhtr] closes it. *)
Theorem qhtr_1RB1LD_1RC1RB_1LA1LA_0RB0LD :
  NonHalt tm_1RB1LD_1RC1RB_1LA1LA_0RB0LD /\ QHBoundTr 32779478 tm_1RB1LD_1RC1RB_1LA1LA_0RB0LD /\ QuasiHaltsTr tm_1RB1LD_1RC1RB_1LA1LA_0RB0LD.
Proof.
  apply (boardph_qhtr tm_1RB1LD_1RC1RB_1LA1LA_0RB0LD pins_1RB1LD_1RC1RB_1LA1LA_0RB0LD FAM 2
                      iarm_1RB1LD_1RC1RB_1LA1LA_0RB0LD 1 1
                      farm_1RB1LD_1RC1RB_1LA1LA_0RB0LD 1 1
                      fm1_1RB1LD_1RC1RB_1LA1LA_0RB0LD fm2_1RB1LD_1RC1RB_1LA1LA_0RB0LD 0 vis_1RB1LD_1RC1RB_1LA1LA_0RB0LD
                      [0] 0 19 32779478).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 1; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1LD_1RC1RB_1LA1LA_0RB0LD.
  - repeat constructor.
