  | _, _ => farm1_0_1RB1LD_1RC1RB_1LA1LB_0RB0LD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1LD_1RC1RB_1LA1LB_0RB0LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1LD_1RC1RB_1LA1LB_0RB0LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
