  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWin 2;SCycR 2;SWinR 7]
  | 1, (StC, S1) => [SWin 2;SCycR 2;SWin 2]
  | 1, (StD, S0) => []
  | 1, (StD, S1) => [SWin 2;SCycR 2;SWinR 9]
  | _, _ => []
  end.

