(** The boot, on the ORIGINAL machine and up to [lift]: the member at index
    15, past the last fire of every pinned instruction. *)
Lemma bootq_1RB1LD_1RC1RB_1LA1RB_0RB0LD :
  stepn tm_1RB1LD_1RC1RB_1LA1RB_0RB0LD 15 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm_1RB1LD_1RC1RB_1LA1RB_0RB0LD 15 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm_1RB1LD_1RC1RB_1LA1RB_0RB0LD 15 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** a pinned instruction fired before the boot: the quasihalt witness *)
Lemma wit_1RB1LD_1RC1RB_1LA1RB_0RB0LD :
  existsb (fun tg => cfires tm_1RB1LD_1RC1RB_1LA1RB_0RB0LD c0 15 tg) pins_1RB1LD_1RC1RB_1LA1RB_0RB0LD = true.
Proof. vm_compute. reflexivity. Qed.

Lemma bnd_1RB1LD_1RC1RB_1LA1RB_0RB0LD : (15 <=? 32779478) = true.
Proof. apply bound_tr_leb; vm_cast_no_check (eq_refl true). Qed.

(** The machine-level theorem, on the QUASIHALTING side: the board above
    runs on the machine wrapped at the pins from the boot member on, and
    [LadderCheckQHTr.boardph_qhtr] closes it. *)
Theorem qhtr_1RB1LD_1RC1RB_1LA1RB_0RB0LD :
  NonHalt tm_1RB1LD_1RC1RB_1LA1RB_0RB0LD /\ QHBoundTr 32779478 tm_1RB1LD_1RC1RB_1LA1RB_0RB0LD /\ QuasiHaltsTr tm_1RB1LD_1RC1RB_1LA1RB_0RB0LD.
Proof.
  apply (boardph_qhtr tm_1RB1LD_1RC1RB_1LA1RB_0RB0LD pins_1RB1LD_1RC1RB_1LA1RB_0RB0LD FAM 1
                      iarm_1RB1LD_1RC1RB_1LA1RB_0RB0LD 1 1
                      farm_1RB1LD_1RC1RB_1LA1RB_0RB0LD 1 1
                      fm1_1RB1LD_1RC1RB_1LA1RB_0RB0LD fm2_1RB1LD_1RC1RB_1LA1RB_0RB0LD 0 vis_1RB1LD_1RC1RB_1LA1RB_0RB0LD
                      [0] 0 15 32779478).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
