Lemma farm_sound_1RB1RB_0LC0RB_1LD1LC_1RA1LA : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 -> RuleSound tm true true (farm_1RB1RB_0LC0RB_1LD1LC_1RA1LA r ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  {
    destruct ph as [|ph].
    { eapply arm_sound; [exact rules_sound_1RB1RB_0LC0RB_1LD1LC_1RA1LA | exact ok_farm1_0_1RB1RB_0LC0RB_1LD1LC_1RA1LA]. }
    destruct ph as [|ph].
