  match r, ph with
  | 1, 0 => farm1_0_1RB1RB_0LC0RB_1LD1LC_1RA1LC
  | _, _ => farm1_0_1RB1RB_0LC0RB_1LD1LC_1RA1LC  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1RB_0LC0RB_1LD1LC_1RA1LC (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1RB_0LC0RB_1LD1LC_1RA1LC (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB1RB_0LC0RB_1LD1LC_1RA1LC (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S1) => [SWin 2;SCycL 2 0;SWinL 6]
  | 1, (StB, S0) => []
  | 1, (StB, S1) => [SWin 2;SCycL 2 0;SWinL 7]
  | 1, (StC, S0) => [SWin 2;SCycL 2 0;SWin 1]
  | 1, (StC, S1) => [SWin 1]
  | 1, (StD, S0) => [SWin 2;SCycL 2 0;SWinL 5]
  | 1, (StD, S1) => [SWin 2;SCycL 2 0;SWin 2]
  | _, _ => []
  end.

