Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1RB_0LC0RB_1LD1LC_1RA1RA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1RB_0LC0RB_1LD1LC_1RA1RA
  | 0, 1 => iarm0_1_1RB1RB_0LC0RB_1LD1LC_1RA1RA
  | _, _ => iarm0_0_1RB1RB_0LC0RB_1LD1LC_1RA1RA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

