    { eapply arm_sound; [exact rules_sound_1RB1RB_0LC0RB_1LD1LC_1RA1RA | exact ok_iarm0_0_1RB1RB_0LC0RB_1LD1LC_1RA1RA]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RB_0LC0RB_1LD1LC_1RA1RA | exact ok_iarm0_1_1RB1RB_0LC0RB_1LD1LC_1RA1RA]. }
    exfalso; lia.
