    the counter advances by, all off this record. *)
Definition fam_1RB1RB_0RC1RD_1LA1LC_0LC0RD : Fam := mkFam 2 [[S0;S0];[S1;S1]] [] [[S0;S1;S1];[S1;S1;S1]] Binary 1 [mkFill 0 [] 0 [] 1;mkFill 1 [] 0 [] 0] StD S0 true [].
Local Notation FAM := fam_1RB1RB_0RC1RD_1LA1LC_0LC0RD.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1RB_0RC1RD_1LA1LC_0LC0RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StD (mkS [S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)])].
Local Notation lad := lad_1RB1RB_0RC1RD_1LA1LC_0LC0RD.

Definition rules_1RB1RB_0RC1RD_1LA1LC_0LC0RD : list LRule := map fst lad.
Local Notation rules := rules_1RB1RB_0RC1RD_1LA1LC_0LC0RD.

Lemma ladder_ok_1RB1RB_0RC1RD_1LA1LC_0LC0RD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1RB_0RC1RD_1LA1LC_0LC0RD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1RB_0RC1RD_1LA1LC_0LC0RD. Qed.

