Lemma farm_sound_1RB1RB_0RC1RD_1LA1LC_0LC0RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 -> RuleSound tm true true (farm_1RB1RB_0RC1RD_1LA1LC_0LC0RD r ph).
Proof.
  intros r ph H0 Hr Hph.
