Lemma farm_lhs_1RB1RB_0RC1RD_1LA1LC_0LC0RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 ->
  lr_lhs (farm_1RB1RB_0RC1RD_1LA1LC_0LC0RD r ph)
    = cls_conf FAM (run_side FAM (fm_b FAM - 1) r (astride 1 1 r)
                      0 ph [] []).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
