Lemma farm_rhs_1RB1RB_0RC1RD_1LA1LC_0LC0RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 ->
  lr_rhs (farm_1RB1RB_0RC1RD_1LA1LC_0LC0RD r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_1RB1RB_0RC1RD_1LA1LC_0LC0RD r ph)
                      (astride 1 1 r) (fm2_1RB1RB_0RC1RD_1LA1LC_0LC0RD r ph)
                      (f_to (fam_fill FAM ph))
                      (f_pre (fam_fill FAM ph)) (f_suf (fam_fill FAM ph))).
