  match r, ph with
  | 1, 0 => farm1_0_1RB1RB_1LB1RC_0RC1LD_1LA0LD
  | 1, 1 => farm1_1_1RB1RB_1LB1RC_0RC1LD_1LA0LD
  | _, _ => farm1_0_1RB1RB_1LB1RC_0RC1LD_1LA0LD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1RB_1LB1RC_0RC1LD_1LA0LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 1, 1 => 1 | _, _ => 0 end.
Definition fm2_1RB1RB_1LB1RC_0RC1LD_1LA0LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 1, 1 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
