Lemma fm12_1RB1RB_1LC0LC_1RD1LB_1RA0RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  fm1_1RB1RB_1LC0LC_1RD1LB_1RA0RD r ph + fm2_1RB1RB_1LC0LC_1RD1LB_1RA0RD r ph
  + (length (f_pre (fam_fill FAM ph)) + length (f_suf (fam_fill FAM ph)))
  = r + f_s (fam_fill FAM ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
