(** The boot, on the ORIGINAL machine and up to [lift]: the member at index
    21, past the last fire of every pinned instruction. *)
Lemma bootq_1RB1RB_1LC1RD_1LA0LC_0RD1LC :
  stepn tm_1RB1RB_1LC1RD_1LA0LC_0RD1LC 21 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm_1RB1RB_1LC1RD_1LA0LC_0RD1LC 21 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm_1RB1RB_1LC1RD_1LA0LC_0RD1LC 21 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

