  d < fm_b FAM - 1 -> r < 1 + 1 ->
  RuleSound tm (negb (fm_left FAM)) (fm_left FAM) (iarm_1RB1RB_1RC1RD_1LA1LC_0LC0RD d r).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RB_1RC1RD_1LA1LC_0LC0RD | exact ok_iarm0_0_1RB1RB_1RC1RD_1LA1LC_0LC0RD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RB_1RC1RD_1LA1LC_0LC0RD | exact ok_iarm0_1_1RB1RB_1RC1RD_1LA1LC_0LC0RD]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

