  match r, t with
  | 1, (StA, S0) => [SWin 2;SCycL 2 0;SWinL 7]
  | 1, (StA, S1) => [SWin 2;SCycL 2 0;SWin 2]
  | 1, (StB, S1) => [SWin 2;SCycL 2 0;SWinL 8]
  | 1, (StC, S0) => [SWin 2;SCycL 2 0;SWin 1]
  | 1, (StC, S1) => [SWin 1]
  | 1, (StD, S0) => []
  | 1, (StD, S1) => [SWin 2;SCycL 2 0;SWinL 9]
  | _, _ => []
  end.

