(** The boot, on the ORIGINAL machine and up to [lift]: the member at index
    22, past the last fire of every pinned instruction. *)
Lemma bootq_1RB1RC_1LC1RA_0RD0LC_0RB1LA :
  stepn tm_1RB1RC_1LC1RA_0RD0LC_0RB1LA 22 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm_1RB1RC_1LC1RA_0RD0LC_0RB1LA 22 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm_1RB1RC_1LC1RA_0RD0LC_0RB1LA 22 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** a pinned instruction fired before the boot: the quasihalt witness *)
