  match r, ph with
  | 1, 0 => farm1_0_1RB1RC_1LC1RD_0RB0LC_1RA0RD
  | _, _ => farm1_0_1RB1RC_1LC1RD_0RB0LC_1RA0RD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1RC_1LC1RD_0RB0LC_1RA0RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1RC_1LC1RD_0RB0LC_1RA0RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
