Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1RC_1LC1RD_1LA0LC_0RD1LC (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1RC_1LC1RD_1LA0LC_0RD1LC
  | 0, 1 => iarm0_1_1RB1RC_1LC1RD_1LA0LC_0RD1LC
  | _, _ => iarm0_0_1RB1RC_1LC1RD_1LA0LC_0RD1LC   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1RC_1LC1RD_1LA0LC_0RD1LC : LRule :=
  mkLRule (mkC StD (mkS [S1;S1] [S1;S1] 1 0 [S0;S1;S1]) S1 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S0;S0] [S0;S0] 1 0 [S0;S0;S0;S1;S1]) S1 (mkS [] [] 0 0 [])) 4 16.
Definition ch_farm1_0_1RB1RC_1LC1RD_1LA0LC_0RD1LC : list rstep := [RB (SWin 2);RB (SCycL 2 0);RB (SWin 5);RB (SWinL 7);RB (SCycR 2);RB (SWin 2)].
Lemma ok_farm1_0_1RB1RC_1LC1RD_1LA0LC_0RD1LC :
  check_arm tm true true rules farm1_0_1RB1RC_1LC1RD_1LA0LC_0RD1LC
            ch_farm1_0_1RB1RC_1LC1RD_1LA0LC_0RD1LC = true.
Proof. vm_compute. reflexivity. Qed.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB1RC_1LC1RD_1LA0LC_0RD1LC (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB1RC_1LC1RD_1LA0LC_0RD1LC
  | _, _ => farm1_0_1RB1RC_1LC1RD_1LA0LC_0RD1LC  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1RC_1LC1RD_1LA0LC_0RD1LC (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1RC_1LC1RD_1LA0LC_0RD1LC (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB1RC_1LC1RD_1LA0LC_0RD1LC (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 2;SCycL 2 0;SWinL 7]
  | 1, (StA, S1) => [SWin 2;SCycL 2 0;SWin 2]
  | 1, (StB, S1) => [SWin 2;SCycL 2 0;SWinL 8]
  | 1, (StC, S0) => [SWin 2;SCycL 2 0;SWin 1]
  | 1, (StC, S1) => [SWin 1]
  | 1, (StD, S0) => [SWin 2;SCycL 2 0;SWinL 9]
  | 1, (StD, S1) => []
  | _, _ => []
  end.

