(** The boot, on the ORIGINAL machine and up to [lift]: the member at index
    19, past the last fire of every pinned instruction. *)
Lemma bootq_1RB1RC_1LC1RD_1LA0LC_0RD1LC :
  stepn tm_1RB1RC_1LC1RD_1LA0LC_0RD1LC 19 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm_1RB1RC_1LC1RD_1LA0LC_0RD1LC 19 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm_1RB1RC_1LC1RD_1LA0LC_0RD1LC 19 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** a pinned instruction fired before the boot: the quasihalt witness *)
Lemma wit_1RB1RC_1LC1RD_1LA0LC_0RD1LC :
  existsb (fun tg => cfires tm_1RB1RC_1LC1RD_1LA0LC_0RD1LC c0 19 tg) pins_1RB1RC_1LC1RD_1LA0LC_0RD1LC = true.
Proof. vm_compute. reflexivity. Qed.

